"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[9054],{19054:e=>{e.exports=JSON.parse('{"meta":{"title":"Muslim Companion Alexa Skill: Athan on Your Echo - iMuslim Life","description":"Muslim Companion plays the Athan on your Amazon Echo at your prayer times, with Quran, adhkar, Hifz Coach and Ramadan mode. Free. Set up at alexa.imuslimlife.com."},"hero":{"title":"Muslim Companion for Alexa","lede":"The Athan at your local prayer times, adhkar after the prayer, Quran recitation and reminders from your masjid, on your Amazon Echo.","live":"\u2714 Live on Alexa","dashboard":"Open Dashboard","tryWeb":"Try Web App","imgAlt":"Amazon Alexa device","athan":"\\"Allahu Akbar...\\"","maghrib":"Maghrib at 7:45 PM"},"how":{"video":"Watch the setup in under a minute","after":"Once the routine is saved, finish your setup: sign in at alexa.imuslimlife.com, or open the Salat-e-Mustaqeem app and tap the Alexa icon.","h2":"How It Works","sub":"Set up your personal muezzin in three simple steps \u2014 it takes less than five minutes.","s1":{"h3":"Enable the Skill","p":"Open the Alexa app on your phone, search for <b>Muslim Companion</b>, and tap <i>Enable to Use</i>. Then say \u201c<q>{{p1}}</q>\u201d to confirm."},"s2":{"h3":"Sign In & Configure","p":"Visit <a>alexa.imuslimlife.com</a>, sign in, confirm your location, choose your Athan voice, and follow your masjid (for example AMCC) for iqamah and Jumu\'ah reminders.","voice":"<b>Or by voice:</b> \u201c<q>{{p1}}</q>\u201d and \u201c<q>{{p2}}</q>\u201d, no dashboard needed. See the voice commands below."},"s3":{"h3":"Create a Routine & Enjoy","p":"In the Alexa app, create one routine: when the <i>Muslim Companion Azan</i> sensor opens, open <i>Muslim Companion</i>. Your Echo then plays the Athan automatically at every prayer time. Our <a>step-by-step setup guide</a> walks you through it with screenshots."}},"features":{"h2":"Key Features","sub":"Everything is set up at alexa.imuslimlife.com, and every extra is off until you turn it on","soon":"Coming soon: scholar review","items":{"athan":{"title":"Athan at your prayer times","description":"Your Echo plays the Athan at your local times for all five prayers, with a choice of Athan voices and a special Fajr Athan."},"masjid":{"title":"Masjid Connect","description":"Follow your masjid (like AMCC) and get a reminder before each iqamah and before Jumu\'ah, with the times your masjid publishes."},"quran":{"title":"Quran recitation","description":"More than 30 renowned reciters. One surah after the Athan, or keep the Quran playing through the day, and pick up where you left off."},"adhkar":{"title":"Adhkar after the prayer","description":"Ayat al-Kursi and the three Quls after each prayer, with Arabic text and English or Urdu translation. Off until you turn it on."},"hifz":{"title":"Hifz Coach","description":"Memorize a few ayahs at a time on your Echo: each ayah three times, then the whole lesson together, with your progress saved. Practice online too."},"ramadan":{"title":"Ramadan mode","description":"A Suhoor reminder before Fajr, Iftar announced at Maghrib, and Makkah Taraweeh recitation after Isha."},"show":{"title":"Echo Show screen","description":"Today\'s prayer times on screen with the next prayer highlighted and a countdown, plus an always-on Prayer Times widget."},"scenes":{"title":"Home Scenes","description":"Dim the lights at the Athan, wake gently before Fajr, or set a calm evening after Isha, using your own Alexa routines."},"duas":{"title":"Duas after the Athan","description":"The Dua after the Athan and the Duas you choose, played on your Echo right after the Athan."},"qibla":{"title":"Qibla direction","description":"Ask which way is the Qibla: the direction from your home in degrees and as a compass point, and how far Makkah is."},"hijri":{"title":"Hijri date & Islamic calendar","description":"Today\'s Hijri date, and how many days until Ramadan, Eid, Ashura, Arafah or the white days. The same dates as your prayer times."},"fasting":{"title":"Sunnah fasting","description":"Ask when the next Sunnah fast is, or get a reminder after Isha the evening before Mondays, Thursdays, the white days, Arafah and Ashura."},"tasbih":{"title":"Tasbih & morning and evening adhkar","description":"Alexa counts dhikr with you (33, 33, 34 after the prayer), with a tap counter on Echo Show, and plays the morning and evening adhkar."},"translation":{"title":"Quran with translation","description":"Play any surah by voice, with English or Urdu after each ayah, and Surah Al-Kahf every Friday."},"daily":{"title":"Daily Dua, Hadith & Names of Allah","description":"A short dua, hadith or one of the 99 Names each day, with its source, reviewed by a scholar before it is published."}}},"screens":{"h2":"See it in action","sub":"Real screens for a family that follows AMCC in Florida: prayer times for their own location, iqamah times published by the masjid.","showAlt":"Echo Show screen: today\'s prayer times with the masjid\'s iqamah times and the next prayer, Maghrib, highlighted with a countdown","showH":"On your Echo Show","showP":"Say \u201c<q>{{p1}}</q>\u201d: the five prayers and sunrise, your masjid\u2019s iqamah next to each one, and the next prayer highlighted with a countdown.","phoneAlt":"My Masjid on a phone: the masjid, today\'s athan and iqamah times, Jumu\'ah, and the Echo reminder choices","phoneH":"On your phone","phoneP":"At <a>alexa.imuslimlife.com</a>, open <b>My Masjid</b> and choose your masjid. You see today\u2019s athan and iqamah times and this Friday\u2019s Jumu\u2019ah, and you choose when your Echo reminds you before the iqamah and Jumu\u2019ah.","widgetAlt":"Prayer Times widget: next prayer Maghrib with countdown, iqamah time and today\'s five prayers","widgetH":"Always-on widget","widgetP":"On Echo Show 8, 10 and 15, add the <b>Prayer Times</b> widget: the next prayer, its countdown and your masjid\u2019s iqamah stay on the home screen."},"voice":{"h2":"Voice Commands","sub":"Everything you can say to Muslim Companion, grouped by feature. Using an AI assistant? <a>Connect it to our prayer times</a>."},"ref":{"langsTitle":"Languages and countries","langsBody":"Muslim Companion understands <b>English</b>, <b>Arabic</b> (\u201c\u0627\u0644\u0631\u0641\u064a\u0642 \u0627\u0644\u0645\u0633\u0644\u0645\u201d) and <b>Hindi</b> (\u201c\u092e\u0941\u0938\u094d\u0932\u093f\u092e \u0915\u092e\u094d\u092a\u0948\u0928\u093f\u092f\u0928\u201d). In English, say the phrases exactly as written, starting with \u201c<q>{{p1}}</q>\u201d (the name is the same in the <b>United States, Canada, the United Kingdom, India and Australia</b>). Choose a language above to see the Arabic or Hindi phrases. Where a phrase has a choice, such as a calculation method, the description lists every option you can say.","soonNote":"Commands marked <b>Coming soon</b> are not available yet; the badge says why.","english":"English","soonSuffix":" \xb7 coming soon","langNote":"<b>{{title}}</b>: set your Alexa language to {{lang}} to use Muslim Companion in {{title}}. The skill\u2019s name in this language is <n>{{name}}</n>. These are the exact phrases it understands; the descriptions stay in English.","langAr":"Arabic (Saudi Arabia)","langHi":"Hindi (India)","all":"All","comingSoon":"Coming soon","showsOnShow":"Shows on Echo Show","whilePlaying":"While Muslim Companion is playing","turnsOff":"Turns the automatic Athan off","tip":"Tip: {{tip}}","footer":"You can also start with \u201c<q>{{p1}}</q>\u201d and then ask. Commands like \u201c<q>next</q>\u201d, \u201c<q>pause</q>\u201d and \u201c<q>stop</q>\u201d work while Muslim Companion is playing."},"api":{"h2":"Powered By Our Time-Tested API","p":"The Muslim Companion Alexa skill is built on top of our robust prayer times API that delivers precise calculations based on your exact location.","methods":{"primary":"23 Calculation Methods + Hanafi or Standard Asr","secondary":"ISNA, Muslim World League, Umm al-Qura, Egyptian, Karachi, Gulf, Kuwait, Qatar, Singapore, France, Turkey, Russia, Tehran and Jafari, set on the dashboard or by voice"},"hijri":{"primary":"Hijri Calendar Integration","secondary":"Get accurate Islamic dates alongside prayer times"},"perf":{"primary":"High Performance","secondary":"Optimized for speed and reliability"},"free":{"primary":"Free for the Community","secondary":"The prayer times API is free to use"},"cta":"Explore Our API","imgAlt":"API illustration"},"cta":{"h2":"Ready to hear the Athan from Alexa?","p":"The skill is live. Set up your personalised prayer schedule in under five minutes.","guide":"See Setup Guide","small":"Free forever \xb7 No app download required \xb7 Works with all Echo devices"},"faq":{"h2":"Common Questions","devices":{"q":"Which Alexa devices does this skill work with?","a":"The Muslim Companion skill works with any Amazon Echo device or Alexa-enabled device. For the best audio experience, we recommend devices with quality speakers such as the Echo, Echo Dot, or Echo Show."},"dst":{"q":"Does the skill automatically adjust for daylight saving time?","a":"Yes, the skill automatically adjusts prayer times based on your location\'s time zone and daylight saving time changes. You\'ll always get accurate prayer times without having to make any manual adjustments."},"choose":{"q":"Can I customize which prayers play the athan?","a":"Absolutely! You can choose which prayer times should play the athan. For example, you might want to enable it only for Fajr, Maghrib and Isha, or for all five daily prayers. You choose this on the Prayer Settings page at alexa.imuslimlife.com."},"cost":{"q":"Is there a cost to use this skill?","a":"The Muslim Companion skill is completely free. The core functionality \u2014 accurate prayer times and automated athan \u2014 remains free for the Muslim community, always."},"offline":{"q":"What if my internet connection goes down?","a":"Your prayer times are calculated in advance, but your Echo needs an internet connection to play the Athan. If your connection is down at prayer time, that Athan may be missed; everything resumes automatically once you are back online."}}}')}}]);